def button(text, href, outline=False):
    return f'<a class="button {"button--outline" if outline else ""}" href="{href}">{text}</a>'

def heading(title, label='Magnesowy Świat', text=''):
    return f'<div class="section-heading"><p class="eyebrow">{label}</p><h2>{title}</h2>{f"<p>{text}</p>" if text else ""}</div>'

def section(content, extra='', id=''):
    return f'<section class="section {extra}"{f" id={id}" if id else ""}><div class="wrap">{content}</div></section>'

def photo(file, alt, eager=False):
    return f'<img src="images/{file}.jpg" alt="{alt}" loading="{"eager" if eager else "lazy"}" width="1000" height="750" decoding="async">'

def hero(title, copy, image, alt, actions, home=False):
    eyebrow = '<p class="eyebrow">Tworzone z myślą o Twoich wspomnieniach</p>' if not home else ""
    return f'<section class="hero {"hero--home" if home else "hero--service"}"><div class="wrap hero-grid"><div class="hero-copy">{eyebrow}<h1>{title}</h1>{copy}<div class="actions">{actions}</div></div><figure class="hero-image">{photo(image,alt,True)}<figcaption class="photo-note">Fotografia inspiracyjna. Nie przedstawia realizacji Magnesowego Świata.</figcaption></figure></div></section>'

def steps(items):
    return '<div class="step-grid">'+''.join(f'<article class="process-step"><span class="number">{i:02}.</span><h3>{t}</h3><p>{p}</p></article>' for i,(t,p) in enumerate(items,1))+'</div>'

def benefits(items):
    return '<div class="benefit-grid">'+''.join(f'<article class="benefit"><span aria-hidden="true" class="eyebrow">{i:02}</span><h3>{t}</h3><p>{p}</p></article>' for i,(t,p) in enumerate(items,1))+'</div>'

def gallery(items):
    out='<div class="gallery">'
    for title,file in items:
        if file:
            out+=f'<figure><button type="button" class="gallery-photo" data-lightbox="images/{file}.jpg" data-caption="{title} — fotografia inspiracyjna" aria-label="Powiększ: {title}">{photo(file,title+" — inspiracja fotograficzna")}</button><figcaption>{title}<small>Zdjęcie inspiracyjne, nie nasza realizacja</small></figcaption></figure>'
        else:
            out+=f'<figure><div class="photo-placeholder"><span aria-hidden="true">▧</span><strong>{title}</strong><small>Miejsce na autentyczne zdjęcie marki</small></div><figcaption>{title}<small>Fotografia do uzupełnienia</small></figcaption></figure>'
    return out+'</div>'

def faq(items):
    return heading('Dobrze wiedzieć','Pytania i odpowiedzi')+'<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'

def field(label,name,type='text',required=False,options=None,full=False):
    id='f-'+name
    attrs=f'id="{id}" name="{name}"'+(' required' if required else '')
    if options is not None:
        control=f'<select {attrs}><option value="">Wybierz opcję</option>'+''.join(f'<option>{escape(x)}</option>' for x in options)+'</select>'
    elif type=='date': control=date_control(attrs)
    elif type=='textarea': control=f'<textarea {attrs} rows="4" maxlength="5000"></textarea>'
    else: control=f'<input {attrs} type="{type}"'+(' min="1" max="10000"' if type=='number' else '')+(' autocomplete="name"' if name=='name' else ' autocomplete="email"' if type=='email' else ' autocomplete="tel"' if type=='tel' else '')+'>'
    return f'<div class="field {"field--full" if full else ""}"><label for="{id}">{label}{" *" if required else ""}</label>{control}</div>'

HIDDEN = '<input type="hidden" name="_subject" value="[NA ŻYWO] Zapytanie o termin | Magnesowy Świat">\n<input type="hidden" name="Rodzaj zapytania" value="Magnesy na żywo">\n<input type="hidden" name="_template" value="table">\n<input type="hidden" name="_captcha" value="false">\n<input type="hidden" name="_url" value="https://magnesowyswiat.pl/magnesy-na-zywo/">\n<input type="hidden" name="_next" value="https://magnesowyswiat.pl/magnesy-na-zywo/?wyslano=1#rezerwacja">\n<input type="text" name="_honey" tabindex="-1" autocomplete="off" aria-hidden="true" style="display:none">'
