def live_form(markup):
    pos = markup.index('<form data-inquiry="live">')
    start = markup.rfind('<div class="preview-notice">', 0, pos)
    end = markup.index('</div>', start) + len('</div>')
    markup = markup[:start] + markup[end:]
    markup = markup.replace('<form data-inquiry="live">', '<form data-inquiry="live" action="https://formsubmit.co/magnesowyswiat@gmail.com" method="POST" accept-charset="UTF-8">\n' + HIDDEN)
    markup = markup.replace('Pola oznaczone * są obowiązkowe. Nie wpisuj danych wrażliwych w wersji demonstracyjnej.', 'Pola oznaczone * są obowiązkowe. Po kliknięciu przejdziesz do wysyłki zapytania.')
    markup = markup.replace('Rozumiem, że to lokalny podgląd i zapytanie nie zostanie wysłane.', CONSENT)
    markup = markup.replace('required name="consent"', 'required name="consent" value="Tak"')
    markup = markup.replace('form[data-inquiry]{display:none}', 'form[data-inquiry="order"]{display:none}')
    for name, label in [('name','Imię i nazwisko'),('phone','Numer telefonu'),('date','Data wydarzenia'),('city','Miejscowość'),('event','Rodzaj wydarzenia'),('guests','Liczba gości'),('package','Wybrany pakiet'),('message','Wiadomość')]:
        markup = markup.replace(f'name="{name}"', f'name="{label}"')
    markup = markup.replace('Włącz JavaScript, aby korzystać z podglądu zdjęć i zapytań.', 'Formularz zapytania o termin działa również bez JavaScript.')
    return markup

def form(order=False):
    fields=field('Imię i nazwisko','name',required=True)+field('Adres e-mail','email','email',True)+field('Telefon','phone','tel')
    if order:
        fields+=field('Liczba magnesów','quantity','number',True)
        fields+='''<div class="field field--full"><label for="photos">Twoje zdjęcia *</label><div class="upload-zone"><input id="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple aria-describedby="photo-help"><p id="photo-help">JPEG, PNG lub WebP. Maksymalnie 20 zdjęć, każde do 10 MB. Podgląd działa wyłącznie w pamięci tej karty przeglądarki. Zdjęcia nie są wysyłane ani zapisywane na serwerze.</p></div><p id="photo-status" role="status"></p><div class="photo-previews" id="photo-previews"></div></div>'''
        fields+=field('Opcjonalny napis lub data','caption')+field('Preferowany sposób dostawy','delivery',options=['Do ustalenia','Przesyłka na adres','Odbiór — do uzgodnienia'])+field('Dane do dostawy','address','textarea',full=True)+field('Uwagi do zamówienia','message','textarea',full=True)
    else:
        fields+=field('Data wydarzenia','date','date',True)+field('Miejscowość','city',required=True)+field('Rodzaj uroczystości','event',required=True,options=['Wesele','Urodziny / osiemnastka','Jubileusz','Event firmowy','Inna uroczystość'])+field('Przybliżona liczba gości','guests','number',True)+field('Wybrany pakiet','package',options=['Mini','Standard','Gold','Premium','Pomóżcie mi wybrać'])+field('Dodatkowa wiadomość','message','textarea',full=True)
    title='Zamów swoje magnesy' if order else 'Porozmawiajmy o Twoim wydarzeniu'
    result = section(f'''<div class="form-layout"><div class="form-intro"><p class="eyebrow">{ 'Twoje zdjęcia. Nasza pasja.' if order else 'Zarezerwuj wspomnienia'}</p><h2>{title}</h2><p>Opisz swój pomysł. Szczegóły, cenę i zakres potwierdzimy indywidualnie przed przyjęciem zamówienia.</p><div class="preview-notice"><strong>Wersja demonstracyjna formularza.</strong><p>Przycisk przygotuje podgląd zapytania. Nie wysyła wiadomości ani zdjęć. Integracja z bezpiecznym systemem wysyłki pozostaje do wdrożenia.</p></div><p>Możesz napisać bezpośrednio:<br><a class="text-link" href="mailto:{EMAIL}">{EMAIL}</a></p></div><form data-inquiry="{'order' if order else 'live'}"><p class="field-hint">Pola oznaczone * są obowiązkowe. Nie wpisuj danych wrażliwych w wersji demonstracyjnej.</p><div class="form-grid">{fields}<label class="consent field--full"><input type="checkbox" required name="consent"> Rozumiem, że to lokalny podgląd i zapytanie nie zostanie wysłane.</label><div class="field--full"><button class="button" type="submit">{'WYŚLIJ ZAPYTANIE O ZAMÓWIENIE' if order else 'ZAPYTAJ O DOSTĘPNOŚĆ TERMINU'}</button><p class="form-status" role="status"></p></div></div></form></div>''','section--soft','zamowienie' if order else 'rezerwacja')
    return enable_order_form(result) if order else live_form(result)

